package com.personal.crm;
import android.content.*;
import org.json.*;
import java.util.*;
/** One app-private snapshot. Shared lock covers UI, contact refresh and notification receivers. */
final class CrmStore {
 static final Object LOCK=new Object(); private final SharedPreferences prefs;
 CrmStore(Context context){prefs=context.getSharedPreferences("crm",Context.MODE_PRIVATE);}
 JSONObject read(){synchronized(LOCK){try{String raw=prefs.getString("state",null);JSONObject data=raw==null?new JSONObject("{\"version\":1,\"people\":[],\"appearance\":{\"top\":\"#203747\",\"bottom\":\"#5a5c61\",\"text\":\"#f4f7fa\"}}"):new JSONObject(raw);validate(data);return data;}catch(JSONException e){throw new IllegalStateException("Could not read CRM",e);}}}
 void write(JSONObject data){synchronized(LOCK){validate(data);try{data.put("revision",read().optLong("revision")+1);}catch(JSONException e){throw new IllegalArgumentException(e);}if(!prefs.edit().putString("state",data.toString()).commit())throw new IllegalStateException("Could not save CRM");}}
 static void validate(JSONObject data){try{if(data.toString().length()>2000000||data.getInt("version")!=1)throw new JSONException("Invalid version or size");JSONArray rows=data.getJSONArray("people");if(rows.length()>5000)throw new JSONException("Too many people");Set<String> ids=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject p=rows.getJSONObject(i);if(!ids.add(text(p,"id",160,true)))throw new JSONException("Duplicate person");text(p,"name",200,true);if(p.has("sortOrder")&&(!(p.get("sortOrder") instanceof Integer)||p.getInt("sortOrder")<0||p.getInt("sortOrder")>=5000))throw new JSONException("Invalid sort order");for(String key:new String[]{"phone","lookupKey","contactId"})text(p,key,500,false);text(p,"notes",20000,false);if(p.has("relationship"))text(p,"relationship",120,false);if(p.has("location"))text(p,"location",500,false);if(p.has("nextSteps"))text(p,"nextSteps",4000,false);if(p.has("email"))text(p,"email",500,false);if(p.has("tags")){JSONArray tags=p.getJSONArray("tags");Set<String> seen=new HashSet<>();for(int j=0;j<tags.length();j++){String tag=tags.getString(j);if(!Arrays.asList("Snapchat","Discord","In person").contains(tag)||!seen.add(tag))throw new JSONException("Invalid tag");}}if(!Arrays.asList("people","dating").contains(p.getString("group")))throw new JSONException("Invalid group");if(!Arrays.asList("Interested","Dating","Paused","In progress","Hiatus","DTF").contains(p.getString("stage")))throw new JSONException("Invalid dating stage");if(!(p.get("reminders") instanceof Boolean))throw new JSONException("Invalid reminders");int count=p.getInt("every");if(count<1||count>365)throw new JSONException("Invalid interval");if(!Arrays.asList("days","weeks","months").contains(p.getString("unit")))throw new JSONException("Invalid interval unit");if(p.getLong("nextAt")<0||p.getLong("lastAt")<0)throw new JSONException("Invalid date");}if(data.has("personalNotes")){JSONArray entries=data.getJSONArray("personalNotes");if(entries.length()>5000)throw new JSONException("Too many personal notes");Set<String> noteIds=new HashSet<>();for(int i=0;i<entries.length();i++){JSONObject note=entries.getJSONObject(i);if(!noteIds.add(text(note,"id",160,true)))throw new JSONException("Duplicate personal note");text(note,"name",200,true);text(note,"notes",20000,false);if(!Arrays.asList("partner","interest").contains(text(note,"kind",20,true)))throw new JSONException("Invalid personal note category");Object created=note.get("createdAt");if(!(created instanceof Long||created instanceof Integer)||note.getLong("createdAt")<0)throw new JSONException("Invalid personal note date");}}if(data.has("relationshipTypes")){
 JSONArray types=data.getJSONArray("relationshipTypes");
 if(types.length()>5000)throw new JSONException("Too many relationship types");
 for(int i=0;i<types.length();i++){
  Object type=types.get(i);
  if(!(type instanceof String)||((String)type).trim().isEmpty()||((String)type).length()>120)throw new JSONException("Invalid relationship type");
 }
}JSONObject colors=data.getJSONObject("appearance");for(String key:new String[]{"top","bottom","text"})if(!colors.getString(key).matches("#[A-Fa-f0-9]{6}"))throw new JSONException("Invalid color");}catch(JSONException e){throw new IllegalArgumentException("Invalid CRM data",e);}}
 private static String text(JSONObject p,String key,int max,boolean required)throws JSONException{Object o=p.get(key);if(!(o instanceof String))throw new JSONException("Invalid text");String s=(String)o;if(s.length()>max||(required&&s.trim().isEmpty()))throw new JSONException("Invalid length");return s;}
}
